import{_ as e,o,c as t,a2 as r}from"./chunks/framework.D7NBeTWs.js";const m=JSON.parse('{"title":"What is MegaloEvolved?","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),i={name:"index.md"};function l(s,a,n,d,g,c){return o(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="what-is-megaloevolved" tabindex="-1">What is MegaloEvolved? <a class="header-anchor" href="#what-is-megaloevolved" aria-label="Permalink to &quot;What is MegaloEvolved?&quot;">​</a></h1><p><strong>MegaloEvolved</strong> (npm package <code>@blamnetwork/megalo</code>) is a TypeScript library for working with Halo <strong>Megalo</strong> scripts — the text-based scripting language used in Halo: Reach gametypes and custom map variants.</p><h2 id="what-this-package-provides" tabindex="-1">What this package provides <a class="header-anchor" href="#what-this-package-provides" aria-label="Permalink to &quot;What this package provides&quot;">​</a></h2><ul><li><strong>Parser</strong> — turn Megalo source (<code>.txt</code>) into an AST (<a href="/MegaloEvolved/main/docs/guide/parsing">Parsing source</a>).</li><li><strong>Compiler</strong> — build game variant or custom variant data from a program (<a href="/MegaloEvolved/main/docs/guide/compiling">Compiling</a>).</li><li><strong>Decompiler</strong> — recover Megalo source from compiled variant data (<a href="/MegaloEvolved/main/docs/guide/decompiling">Decompiling</a>).</li><li><strong>BLF integration</strong> — extract, patch, and round-trip gametypes inside BLF files via <a href="https://blam-network.github.io/blf/" target="_blank" rel="noreferrer">@blamnetwork/blf</a> (<a href="/MegaloEvolved/main/docs/guide/gametypes">Gametypes &amp; BLF</a>).</li><li><strong>Megalo versions</strong> — Reach MCC and Xbox 360 TU1 (<a href="/MegaloEvolved/main/docs/guide/megalo-versions">Megalo versions</a>).</li><li><strong>Language reference</strong> — Bungie Megalo scripting concepts and per-build action tables (<a href="/MegaloEvolved/main/docs/language/">Megalo language</a>).</li></ul><p>Megalo struct layouts and BLF chunk I/O come from <code>@blamnetwork/blf</code> and <a href="https://www.npmjs.com/package/@craftycodie/cstruct" target="_blank" rel="noreferrer">@craftycodie/cstruct</a>, which npm installs automatically as dependencies.</p><h2 id="get-started" tabindex="-1">Get started <a class="header-anchor" href="#get-started" aria-label="Permalink to &quot;Get started&quot;">​</a></h2><p>See <a href="/MegaloEvolved/main/docs/guide/quick-start">Install &amp; quick start</a>.</p><p>Release history: <a href="/MegaloEvolved/main/docs/changelog">Changelog</a>.</p>',8)])])}const h=e(i,[["render",l]]);export{m as __pageData,h as default};
